#include <stdio.h>
#include <queue>
#include <ctype.h>
#include <vector>
#include <string.h>
using namespace std;

#define INF 12345678

struct Pos {
    int x, y, num;
};

struct Cap {
    int arr[1000];
    int cnt;
    int flag;
};

Cap cap[100][100];
vector<int> g[1000];
int n, t;
int left_[1000], right_[1000], vis[1000];
char a[1000][1000], b[1000][1000];
int da[1000][1000], db[1000][1000];
queue<Pos> qu;

void bfs1(Pos s);
void bfs2(Pos s);
int matching(int m);
bool dfs(int u);

int main() {
    int i, j, k, l;
    Pos p, q;

    scanf("%d %d", &n, &t);

    for (i = 0; i <= n; i++)
        for (j = 0; j <= n; j++)
            da[i][j] = INF;

    for (i = 0; i < n; i++) scanf("%s", a[i]);
    for (i = 0; i < n; i++) scanf("%s", b[i]);

    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++)
            if (a[i][j] == 'Z') {
                p.x = i; p.y = j;
                bfs1(p);
            }

    int id = 1;
    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++)
            if (isdigit(b[i][j])) {
                k = b[i][j] - '0';
                if (k > 0) cap[i][j].flag = 1;
                cap[i][j].cnt = k;
                for (l = 1; l <= k; l++)
                    cap[i][j].arr[l] = id++;
            }

    id = 1;
    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++)
            if (isdigit(a[i][j])) {
                k = a[i][j] - '0';
                for (l = 1; l <= k; l++) {
                    p.x = i; p.y = j; p.num = id++;
                    bfs2(p);
                }
            }

    printf("%d\n", matching(id - 1));
    return 0;
}

bool dfs(int u) {
    if (vis[u]) return false;
    vis[u] = 1;
    for (int i = 0; i < (int)g[u].size(); i++) {
        int v = g[u][i];
        if (left_[v] == -1) {
            left_[v] = u;
            right_[u] = i;
            return true;
        } else if (dfs(left_[v])) {
            left_[v] = u;
            right_[u] = i;
            return true;
        }
    }
    return false;
}

int matching(int m) {
    memset(left_, -1, sizeof(left_));
    memset(right_, -1, sizeof(right_));
    bool done;
    do {
        done = true;
        memset(vis, 0, sizeof(vis));
        for (int i = 1; i <= m; i++)
            if (right_[i] == -1 && dfs(i))
                done = false;
    } while (!done);
    int cnt = 0;
    for (int i = 1; i <= m; i++)
        if (right_[i] != -1) cnt++;
    return cnt;
}

void bfs2(Pos s) {
    int i, j, k, l;
    Pos p, q;
    for (i = 0; i <= n; i++)
        for (j = 0; j <= n; j++)
            db[i][j] = INF;
    i = s.x; j = s.y;
    db[i][j] = 0;
    qu.push(s);
    while (!qu.empty()) {
        p = qu.front(); qu.pop();
        i = p.x; j = p.y;
        if (db[i][j] > t) continue;
        if (a[i][j] == 'Y') continue;
        if (cap[i][j].flag) {
            if (db[i][j] <= t && db[i][j] <= da[i][j]) {
                for (k = 1; k <= cap[i][j].cnt; k++)
                    g[s.num].push_back(cap[i][j].arr[k]);
            }
        }
        if (db[i][j] >= da[i][j]) continue;
        // up
        if (i - 1 >= 0 && db[i - 1][j] > db[i][j] + 1) {
            db[i - 1][j] = db[i][j] + 1;
            q.x = i - 1; q.y = j;
            qu.push(q);
        }
        // down
        if (i + 1 < n && db[i + 1][j] > db[i][j] + 1) {
            db[i + 1][j] = db[i][j] + 1;
            q.x = i + 1; q.y = j;
            qu.push(q);
        }
        // left
        if (j - 1 >= 0 && db[i][j - 1] > db[i][j] + 1) {
            db[i][j - 1] = db[i][j] + 1;
            q.x = i; q.y = j - 1;
            qu.push(q);
        }
        // right
        if (j + 1 < n && db[i][j + 1] > db[i][j] + 1) {
            db[i][j + 1] = db[i][j] + 1;
            q.x = i; q.y = j + 1;
            qu.push(q);
        }
    }
}

void bfs1(Pos s) {
    int i, j;
    Pos p, q;
    i = s.x; j = s.y;
    da[i][j] = 0;
    qu.push(s);
    while (!qu.empty()) {
        p = qu.front(); qu.pop();
        i = p.x; j = p.y;
        if (a[i][j] == 'Y') continue;
        // up
        if (i - 1 >= 0 && da[i - 1][j] > da[i][j] + 1) {
            da[i - 1][j] = da[i][j] + 1;
            q.x = i - 1; q.y = j;
            qu.push(q);
        }
        // down
        if (i + 1 < n && da[i + 1][j] > da[i][j] + 1) {
            da[i + 1][j] = da[i][j] + 1;
            q.x = i + 1; q.y = j;
            qu.push(q);
        }
        // left
        if (j - 1 >= 0 && da[i][j - 1] > da[i][j] + 1) {
            da[i][j - 1] = da[i][j] + 1;
            q.x = i; q.y = j - 1;
            qu.push(q);
        }
        // right
        if (j + 1 < n && da[i][j + 1] > da[i][j] + 1) {
            da[i][j + 1] = da[i][j] + 1;
            q.x = i; q.y = j + 1;
            qu.push(q);
        }
    }
}
